import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useLanguage } from '../../context/LanguageContext';
import { useTheme } from '../../context/ThemeContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import advertService from '../../services/advertService';
import styles from './AddAdvertPage.module.css';

const AddAdvertPage = () => {
    const navigate = useNavigate();
    const { user } = useAuth();
    const { t } = useLanguage();
    const { theme } = useTheme();
    const [searchParams] = useSearchParams();
    const editId = searchParams.get('edit');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [formData, setFormData] = useState({
        address: '', date: '', startTime: '18:00', endTime: '20:00',
        gameLevel: 'D2', cost: '', peopleCount: '', description: ''
    });
    const levels = ['D1', 'D2', 'D3', 'D4', 'D4Plus'];

    useEffect(() => { if (editId) loadAdvert(editId); }, [editId]);

    const loadAdvert = async (id) => {
        try {
            const response = await advertService.getAdvertById(id);
            const advert = response.advert;
            setFormData({
                address: advert.address, date: advert.date, startTime: advert.startTime?.slice(0,5),
                endTime: advert.endTime?.slice(0,5), gameLevel: advert.gameLevel, cost: advert.cost,
                peopleCount: advert.peopleCount, description: advert.description || ''
            });
        } catch (err) { setError(t('loadError')); }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            const formDataToSend = {
                ...formData,
                date: formData.date
            };

            if (editId) {
                await advertService.updateAdvert(editId, formDataToSend);
            } else {
                await advertService.createAdvert(formDataToSend);
            }
            navigate('/');
        } catch (err) {
            setError(err.message || t('saveError'));
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className={styles.addAdvertPage}>
            <div className={styles.container}>
                <div className={styles.card}>
                    <h1 className={styles.title}>{editId ? t('editAdvert') : t('createAdvert')}</h1>
                    {error && <div className={styles.error}>{error}</div>}
                    <form onSubmit={handleSubmit} className={styles.form}>
                        <Input label={t('address')} placeholder={t('addressPlaceholder')} value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} required />
                        <Input label={t('date')} type="date" value={formData.date} onChange={(e) => setFormData({...formData, date: e.target.value})} required />
                        <div className={styles.timeRow}>
                            <Input label={t('startTime')} type="time" value={formData.startTime} onChange={(e) => setFormData({...formData, startTime: e.target.value})} required />
                            <Input label={t('endTime')} type="time" value={formData.endTime} onChange={(e) => setFormData({...formData, endTime: e.target.value})} required />
                        </div>
                        <div className={styles.levelSection}>
                            <label className={styles.label}>{t('gameLevel')} *</label>
                            <div className={styles.levelButtons}>
                                {levels.map(level => (<ToggleButton key={level} label={level === 'D4Plus' ? 'D4+' : level} isActive={formData.gameLevel === level} onClick={() => setFormData({...formData, gameLevel: level})} />))}
                            </div>
                        </div>
                        <div className={styles.row}>
                            <Input label={t('cost')} type="number" step="0.01" placeholder="25" value={formData.cost} onChange={(e) => setFormData({...formData, cost: e.target.value})} required />
                            <Input label={t('peopleCount')} type="number" placeholder="12" value={formData.peopleCount} onChange={(e) => setFormData({...formData, peopleCount: e.target.value})} required />
                        </div>
                        <textarea className={styles.textarea} placeholder={t('descriptionPlaceholder')} rows="4" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} />
                        <div className={styles.actions}>
                            <Button type="button" variant="outline" onClick={() => navigate(-1)}>{t('cancel')}</Button>
                            <Button type="submit" loading={loading}>{editId ? t('save') : t('create')}</Button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default AddAdvertPage;
